def _split_at_impl(iterable, pred, keep_separator=False, maxsplit=None):
    buf = []
    splits = 0
    for item in iterable:
        if pred(item):
            if keep_separator:
                buf.append(item)
            yield buf
            buf = []
            splits += 1
            if maxsplit is not None and splits >= maxsplit:
                # Yield remaining items
                buf.extend(iterable)
                if buf:
                    yield buf
                return
        else:
            buf.append(item)
    if buf:
        yield buf

